import { RoutezFeatureModule } from "@_core/_route";
import { Routes } from "@angular/router";
import { Library } from "./library/library";
import { LibraryAdd } from "./library/library-add/library-add";
import { LibraryCabinet } from "./library-cabinet/library-cabinet";
import { LibraryCabinetAdd } from "./library-cabinet/library-cabinet-add/library-cabinet-add";
import { LibraryShelf } from "./library-shelf/library-shelf";
import { LibraryShelfAdd } from "./library-shelf/library-shelf-add/library-shelf-add";
import { LibraryBook } from "./library-book/library-book";
import { LibraryBookAdd } from "./library-book/library-book-add/library-book-add";
import { BookIssue } from "./book-issue/book-issue";
import { BookIssueAdd } from "./book-issue/book-issue-add/book-issue-add";

export const Routez: Routes = new RoutezFeatureModule(
  ['Libarary', 'Attendance'],
  'feature/library'
)
.feature(
  Library,
  LibraryAdd,
  'library',
  'Library'
)
.feature(
  LibraryCabinet,
  LibraryCabinetAdd,
  'library-cabinet',
  'Library Cabinet'
)
.feature(
  LibraryShelf,
  LibraryShelfAdd,
  'library-shelf',
  'Library Shelf'
)
.feature(
  LibraryBook,
  LibraryBookAdd,
  'library-book',
  'Library Book'
)
.feature(
  BookIssue,
  BookIssueAdd,
  'book-issue',
  'Book Issue'
)
.build();
